const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();

const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

const requesterId = parseInt(match[1], 10);
const body = $input.first().json.body || {};
const contactId = parseInt(body.id, 10);

if (!Number.isInteger(contactId)) throw new Error('"id" must be an integer.');

// Only fields actually present in the request body get updated (true
// partial-update semantics) — an omitted key leaves that column untouched,
// while a key explicitly sent (even as '') sets/clears it. This lets
// callers like the "do not contact" toggle send just {id, do_not_contact}
// without wiping every other field, while the full edit form can still
// clear a field by submitting an empty string.
function field(...names) {
  for (const name of names) {
    if (body[name] !== undefined) return (body[name] ?? '').toString().trim();
  }
  return undefined;
}

const accountId = body.account_id === undefined
  ? undefined
  : (body.account_id === null || body.account_id === '')
    ? null
    : parseInt(body.account_id, 10);

if (accountId !== undefined && accountId !== null && !Number.isInteger(accountId)) {
  throw new Error('"account_id" must be an integer or null.');
}

return [{
  json: {
    requesterId,
    contactId,
    first_name: field('first_name'),
    last_name: field('last_name'),
    job_title: field('job_title'),
    account_id: accountId,
    email: field('email'),
    secondary_email: field('secondary_email'),
    phone: field('phone'),
    secondary_phone: field('secondary_phone'),
    linkedin_url: field('linkedin_url'),
    lead_status: field('lead_status', 'status'),
    lead_source: field('lead_source'),
    city: field('city'),
    state: field('state'),
    zip_code: field('zip_code'),
    country: field('country'),
    do_not_contact: body.do_not_contact === undefined ? undefined : (body.do_not_contact === true || body.do_not_contact === 'true')
  }
}];

const requester = $input.first().json;
const c = $('Parse Token & Payload').first().json;

if (!requester.id || !requester.active) throw new Error('Invalid session.');

// Only build a SET clause for fields the caller actually included in the
// request body (see "Parse Token & Payload") — omitted fields stay
// untouched, and a field explicitly sent as '' now genuinely clears it
// instead of silently falling back to the old value.
const fieldColumns = [
  'first_name', 'last_name', 'job_title', 'account_id',
  'email', 'secondary_email', 'phone', 'secondary_phone', 'linkedin_url',
  'lead_status', 'lead_source', 'city', 'state', 'zip_code', 'country',
  'do_not_contact',
];

const setClauses = [];
const queryParams = [];
let idx = 1;

for (const col of fieldColumns) {
  if (c[col] === undefined) continue;
  setClauses.push(`${col} = $${idx}`);
  queryParams.push(c[col]);
  idx++;
}

setClauses.push('updated_at = NOW()');

const sqlQuery = `
  UPDATE contacts SET
    ${setClauses.join(',\n    ')}
  WHERE id = $${idx} AND ($${idx + 1} = 'admin' OR owner_id = $${idx + 2})
  RETURNING *;
`;

queryParams.push(c.contactId, requester.role, requester.id);

return [{ json: { sqlQuery, queryParams } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) {
  throw new Error('Contact not found or you do not have permission to edit it.');
}
return [{ json: { success: true, contact: result.json } }];
